const el = (selector) => document.querySelector(selector);
const menu = el('#menu'), story = el('#story'), player = el('audio');
const time = seconds => Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0');
let ticket;
function finish() {
  player.pause();
  player.removeAttribute('src');
  player.load();
  story.hidden = true;
  menu.hidden = false;
  ticket.focus();
  window.scrollTo(0, 0);
}
function openInterview(item, button) {
  ticket = button;
  el('#number').textContent = item.id;
  el('#title').textContent = item.title;
  el('#role').textContent = item.role + ' · ' + time(item.duration);
  el('#tease').textContent = item.tease;
  el('#status').textContent = '';
  el('details').open = false;
  el('dl').textContent = '';
  item.lines.forEach((line, i) => {
    const who = document.createElement('dt'), speech = document.createElement('dd');
    who.textContent = i % 2 ? item.role : 'Interviewer';
    speech.textContent = line;
    el('dl').append(who, speech);
  });
  player.src = 'audio/' + item.id + '.mp3';
  menu.hidden = true;
  story.hidden = false;
  el('#title').focus();
  window.scrollTo(0, 0);
}
for (const item of interviews) {
  const button = document.createElement('button');
  button.className = 'ticket';
  button.innerHTML = '<span class="num"></span><span class="copy"><strong></strong><small></small><span class="meta"></span></span>';
  button.querySelector('.num').textContent = item.id;
  button.querySelector('strong').textContent = item.title;
  button.querySelector('small').textContent = item.tease;
  button.querySelector('.meta').textContent = item.role + ' · ' + time(item.duration);
  button.onclick = () => openInterview(item, button);
  el('#tickets').append(button);
}
el('#back').onclick = finish;
player.onended = () => { el('#status').textContent = 'Interview finished. If someone is waiting, select All topics and offer your seat.'; };
player.onplay = () => { el('#status').textContent = ''; };
player.onerror = () => { if (player.hasAttribute('src')) el('#status').textContent = 'Audio unavailable. Open Read the interview below.'; };

:root {
  color-scheme: light;
  --ink: #1b312a;
  --muted: #48574c;
  --hall: #183c33;
  --cream: #f6efe2;
  --paper: #fffaf0;
  --brass: #e8b660;
  --rule: #a89b83;
  --rust: #93442e;
  --serif: Georgia, "Times New Roman", serif;
  --sans: system-ui, sans-serif;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  background: var(--cream);
  color: var(--ink);
  font: 1rem/1.5 var(--sans);
  margin: 0;
}

button, input { font: inherit; }
button, summary, input[type="range"] { cursor: pointer; }
button:focus-visible, summary:focus-visible, input:focus-visible {
  outline: 3px solid var(--rust);
  outline-offset: 4px;
}
h2[tabindex="-1"]:focus { outline: 2px solid var(--rust); outline-offset: 4px; }

.marquee {
  background: var(--hall);
  color: var(--paper);
  border-bottom: 5px solid var(--brass);
  overflow: hidden;
}

.marquee-inner, .content {
  max-width: 82rem;
  margin: 0 auto;
  padding-inline: clamp(1.125rem, 5vw, 5rem);
}

.marquee-inner {
  min-height: 12rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  padding-block: 1.8rem 2.1rem;
}

.marquee-copy { position: relative; z-index: 1; }
.eyebrow {
  color: var(--brass);
  font-size: .82rem;
  font-weight: 750;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.marquee p { margin: 0; }
h1 {
  font: 700 clamp(2.7rem, 6.2vw, 5.4rem)/1.02 var(--serif);
  letter-spacing: -.053em;
  margin: .24rem 0 .5rem;
}

.roof {
  display: flex;
  align-items: flex-end;
  gap: .55rem;
  color: var(--brass);
  opacity: .84;
  position: absolute;
  right: clamp(1.125rem, 5vw, 5rem);
  bottom: -1px;
}

.roof span {
  width: clamp(3rem, 7.2vw, 6.4rem);
  height: clamp(4.8rem, 10.5vw, 8rem);
  border: 2px solid currentColor;
  border-bottom: 0;
  border-radius: 6.4rem 6.4rem 0 0;
  background:
    linear-gradient(90deg, transparent calc(50% - .5px), currentColor calc(50% - .5px) calc(50% + .5px), transparent calc(50% + .5px)),
    linear-gradient(transparent 36%, currentColor 36% calc(36% + 1px), transparent calc(36% + 1px) 62%, currentColor 62% calc(62% + 1px), transparent calc(62% + 1px));
}
.roof span:nth-child(2) { height: clamp(6.2rem, 13vw, 10rem); }

.content { padding-block: 1.75rem; }
.section-head { margin-bottom: 1rem; }
h2 {
  font: 700 clamp(1.85rem, 3.4vw, 2.8rem)/1.14 var(--serif);
  letter-spacing: -.035em;
  margin: 0;
}
.section-head p, .interview-head p { color: var(--muted); margin: .3rem 0 0; }

.topics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: .75rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.topic {
  display: flex;
  align-items: flex-start;
  text-align: left;
  gap: .85rem;
  width: 100%;
  min-height: 7.4rem;
  height: 100%;
  padding: 1rem;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--rule);
  border-bottom: 3px solid var(--rule);
  border-radius: .3rem;
  touch-action: manipulation;
}
.topic:hover { border-color: var(--hall); background: #fcf1db; }
.topic:active { background: #f5e1b9; }
.ticket {
  display: inline-grid;
  place-items: center;
  flex: none;
  min-width: 2.6rem;
  min-height: 2.6rem;
  border: 1px solid #644526;
  border-radius: .2rem;
  background: var(--brass);
  color: #252b22;
  font-size: .95rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.topic-copy { display: grid; gap: .2rem; min-width: 0; flex: 1; }
.topic-name { font: 700 clamp(1.2rem, 2vw, 1.55rem)/1.13 var(--serif); }
.topic-teaser { color: var(--muted); font-size: .92rem; line-height: 1.35; }
.topic-time, .times { font-size: .83rem; font-variant-numeric: tabular-nums; }
.topic-time { color: var(--rust); font-weight: 750; margin-top: .15rem; }

.room-note {
  margin-top: 1.25rem;
  padding: .85rem 0 .15rem;
  border-top: 1px solid var(--rule);
  color: var(--muted);
  font-size: .95rem;
}
.room-note strong { color: var(--ink); }

#detail { max-width: 52rem; }
.back {
  min-height: 2.75rem;
  padding: .45rem .75rem;
  color: var(--hall);
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: .25rem;
  font-weight: 700;
}
.back:hover, summary:hover { background: #f5e1b9; }
.back span { margin-right: .3rem; }
.interview-head {
  display: flex;
  align-items: flex-start;
  gap: .8rem;
  margin: 1.15rem 0;
}
.interview-head .ticket { margin-top: .12rem; }
.player, details {
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: .3rem;
}
.player { padding: .8rem 1rem; margin-bottom: .75rem; }
.player-controls { display: flex; gap: 1.15rem; align-items: center; }
.play {
  color: var(--paper);
  background: var(--hall);
  border: 2px solid var(--hall);
  border-radius: .25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .6rem;
  min-height: 3rem;
  min-width: 7.6rem;
  padding: .35rem .6rem;
  font-weight: 750;
}
.play:hover { background: #28594c; }
.play:active { background: #142c25; }
.play:disabled { opacity: .64; cursor: default; }
.play-icon {
  width: 0;
  height: 0;
  border-block: .37rem solid transparent;
  border-left: .58rem solid currentColor;
}
.play[data-playing="true"] .play-icon {
  width: .62rem;
  height: .75rem;
  border: 0;
  border-inline: .19rem solid currentColor;
}
.seek { min-width: 0; flex: 1; }
.seek input { width: 100%; height: 2.75rem; display: block; margin: 0; accent-color: var(--hall); }
.times { display: flex; justify-content: space-between; margin-top: -.27rem; color: var(--muted); }
#player-status { color: var(--muted); font-size: .9rem; margin: .55rem 0 0; }
#player-status:empty { margin: 0; }

summary { padding: .65rem 1rem; min-height: 2.75rem; font-weight: 750; }
details[open] summary { border-bottom: 1px solid var(--rule); }
.transcript { padding: .15rem 1rem .5rem; max-width: 68ch; }
.transcript p { margin: .8rem 0; }
.transcript strong { display: block; color: var(--rust); }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (max-width: 55rem) {
  .topics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 45rem) {
  .roof { display: none; }
  .marquee-inner { min-height: auto; padding-block: 1.3rem 1.5rem; }
}
@media (max-width: 34rem) {
  .topics { grid-template-columns: 1fr; }
  .topic { min-height: 5rem; }
  .player-controls { flex-wrap: wrap; gap: .25rem 1rem; }
  .seek { flex-basis: 8rem; }
}

"use strict";

const menu = document.querySelector("#menu");
const topics = document.querySelector("#topics");
const detail = document.querySelector("#detail");
const title = document.querySelector("#interview-title");
const transcript = document.querySelector("#transcript");
const transcriptText = document.querySelector("#transcript-text");
const play = document.querySelector("#play");
const playLabel = document.querySelector("#play-label");
const position = document.querySelector("#position");
const elapsed = document.querySelector("#elapsed");
const duration = document.querySelector("#duration");
const playerStatus = document.querySelector("#player-status");
let player = null;
let previousButton = null;

function clockTime(value) {
  const seconds = Math.floor(value);
  return Math.floor(seconds / 60) + ":" + String(seconds % 60).padStart(2, "0");
}

function spokenTime(value) {
  const seconds = Math.floor(value);
  const minutes = Math.floor(seconds / 60);
  return (minutes ? minutes + " minute" + (minutes === 1 ? " " : "s ") : "") +
    (seconds % 60) + " seconds";
}

function showTime(current, total) {
  elapsed.textContent = clockTime(current);
  duration.textContent = clockTime(total);
  position.value = Math.min(Math.floor(current), Number(position.max));
  position.setAttribute("aria-valuetext", spokenTime(current) + " of " + spokenTime(total));
}

function showPlaying(playing) {
  play.dataset.playing = String(playing);
  playLabel.textContent = playing ? "Pause" : "Play";
}

function showAudioError() {
  showPlaying(false);
  play.disabled = true;
  position.disabled = true;
  playerStatus.textContent = "Audio unavailable. You can read this interview below.";
}

function makeText(tag, className, content) {
  const element = document.createElement(tag);
  element.className = className;
  element.textContent = content;
  return element;
}

function openInterview(interview, button) {
  previousButton = button;
  title.textContent = interview.title;
  document.querySelector("#interview-number").textContent = interview.number;
  document.querySelector("#interview-role").textContent = interview.role;
  transcript.open = false;
  transcriptText.textContent = "";
  for (const [speaker, words] of interview.turns) {
    const line = makeText("p", "", "");
    line.append(makeText("strong", "", speaker), document.createTextNode(words));
    transcriptText.append(line);
  }

  showPlaying(false);
  play.disabled = false;
  position.disabled = true;
  position.max = interview.seconds;
  showTime(0, interview.seconds);
  playerStatus.textContent = "";
  menu.hidden = true;
  detail.hidden = false;
  title.focus();

  const audio = new Audio();
  player = audio;
  audio.preload = "metadata";
  const whileSelected = (callback) => () => {
    if (player === audio) callback();
  };

  audio.addEventListener("loadedmetadata", whileSelected(() => {
    position.max = Math.round(audio.duration);
    position.disabled = false;
    showTime(audio.currentTime, Math.round(audio.duration));
  }));
  audio.addEventListener("timeupdate", whileSelected(() => {
    if (Number.isFinite(audio.duration)) showTime(audio.currentTime, Math.round(audio.duration));
  }));
  audio.addEventListener("play", whileSelected(() => {
    showPlaying(true);
    playerStatus.textContent = "";
  }));
  audio.addEventListener("pause", whileSelected(() => showPlaying(false)));
  audio.addEventListener("ended", whileSelected(() => {
    showPlaying(false);
    const total = Math.round(audio.duration);
    showTime(total, total);
    playerStatus.textContent = "Interview finished. If someone is waiting, please free the seat.";
  }));
  audio.addEventListener("error", whileSelected(showAudioError));
  audio.src = "audio/" + interview.number + "-" + interview.slug + ".mp3";
}

for (const interview of interviews) {
  const item = document.createElement("li");
  const button = makeText("button", "topic", "");
  button.type = "button";
  const copy = makeText("span", "topic-copy", "");
  const time = makeText("span", "topic-time", clockTime(interview.seconds));
  time.setAttribute("aria-label", spokenTime(interview.seconds));
  copy.append(makeText("span", "topic-name", interview.title),
    makeText("span", "topic-teaser", interview.teaser), time);
  button.append(makeText("span", "ticket", interview.number), copy);
  button.addEventListener("click", () => openInterview(interview, button));
  item.append(button);
  topics.append(item);
}

play.addEventListener("click", async () => {
  const audio = player;
  if (!audio) return;
  if (!audio.paused) {
    audio.pause();
    return;
  }
  if (audio.ended) audio.currentTime = 0;
  try {
    await audio.play();
  } catch (error) {
    if (player === audio && error.name !== "AbortError") {
      if (audio.error) showAudioError();
      else playerStatus.textContent = "Playback could not start. Try Play again or read the transcript.";
    }
  }
});

position.addEventListener("input", () => {
  if (player && Number.isFinite(player.duration)) {
    player.currentTime = position.value === position.max ? player.duration : Number(position.value);
  }
});

document.querySelector("#back").addEventListener("click", () => {
  const audio = player;
  player = null;
  audio.pause();
  audio.removeAttribute("src");
  audio.load();
  detail.hidden = true;
  menu.hidden = false;
  previousButton.focus();
});
